/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `ReduceStockAfterOrder` AFTER INSERT ON `orderdetails` FOR EACH ROW BEGIN
    UPDATE Products
    SET unitsInStock = unitsInStock - NEW.quantity
    WHERE productID = NEW.productID;
END */;;
