DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `CheckReorderProducts`()
BEGIN
    SELECT
        productID,
        productName,
        unitsInStock,
        reorderLevel
    FROM Products
    WHERE unitsInStock <= reorderLevel;
END ;;
DELIMITER ;
